77: bool _finish_create(int fh, _filestream_callback* callback, std::ios_base::openmode mode, int /* prot */)
78: {
79:     if (fh != -1)
80:     {
81:         // Buffer reads internally if and only if we're just reading (not also writing) and
82:         // if the file is opened exclusively. If either is false, we're better off just
83:         // letting the OS do its buffering, even if it means that prompt reads won't
84:         // happen.
85:         bool buffer = (mode == std::ios_base::in);
86: 
87:         // seek to end if requested
88:         if (mode & std::ios_base::ate)
89:         {
90:             lseek(fh, 0, SEEK_END);
91:         }
92: 
93:         auto info = new _file_info_impl(fh, mode, buffer);
94: 
95:         if (mode & std::ios_base::app || mode & std::ios_base::ate)
96:         {
97:             info->m_wrpos = static_cast<size_t>(-1); // Start at the end of the file.
98:         }
99: 
100:         callback->on_opened(info);
101:         return true;
102:     }
103:     else
104:     {
105:         callback->on_error(std::make_exception_ptr(utility::details::create_system_error(errno)));
106:         return false;
107:     }
108: }
