110: int get_open_flags(std::ios_base::openmode mode)
111: {
112:     int result = 0;
113:     if (mode & std::ios_base::in)
114:     {
115:         if (mode & std::ios_base::out)
116:         {
117:             result = O_RDWR;
118:         }
119:         else
120:         {
121:             result = O_RDONLY;
122:         }
123:     }
124:     else if (mode & std::ios_base::out)
125:     {
126:         result = O_WRONLY | O_CREAT;
127:     }
128: 
129:     if (mode & std::ios_base::app)
130:     {
131:         result |= O_APPEND;
132:     }
133: 
134:     if (mode & std::ios_base::trunc)
135:     {
136:         result |= O_TRUNC | O_CREAT;
137:     }
138: 
139:     return result;
