181: /// True does not signal that the file will eventually be successfully closed, just that the process was started.
182: /// </remarks>
183: bool _close_fsb_nolock(_file_info** info, Concurrency::streams::details::_filestream_callback* callback)
184: {
185:     if (callback == nullptr) return false;
186:     if (info == nullptr || *info == nullptr) return false;
187: 
188:     _file_info_impl* fInfo = static_cast<_file_info_impl*>(*info);
189: 
190:     if (fInfo->m_handle == -1) return false;
191: 
192:     // Since closing a file may involve waiting for outstanding writes which can take some time
193:     // if the file is on a network share, the close action is done in a separate task, as
194:     // CloseHandle doesn't have I/O completion events.
195:     pplx::create_task([=]() -> void {
196:         bool result = false;
197: 
198:         {
199:             pplx::extensibility::scoped_recursive_lock_t lock(fInfo->m_lock);
200: 
201:             if (fInfo->m_handle != -1)
202:             {
203:                 result = close(fInfo->m_handle) != -1;
204:             }
205: 
206:             if (fInfo->m_buffer != nullptr)
207:             {
208:                 delete[] fInfo->m_buffer;
209:             }
210:         }
211: 
212:         delete fInfo;
213:         if (result)
214:         {
215:             callback->on_closed();
216:         }
217:         else
218:         {
219:             callback->on_error(std::make_exception_ptr(utility::details::create_system_error(errno)));
220:         }
221:     });
222: 
223:     *info = nullptr;
224: 
225:     return true;
226: }
