238: /// <summary>
239: /// Initiate an asynchronous (overlapped) write to the file stream.
240: /// </summary>
241: /// <param name="info">The file info record of the file</param>
242: /// <param name="callback">A pointer to the callback interface to invoke when the write request is completed.</param>
243: /// <param name="ptr">A pointer to the data to write</param>
244: /// <param name="count">The size (in bytes) of the data</param>
245: /// <returns>0 if the write request is still outstanding, -1 if the request failed, otherwise the size of the data
246: /// written</returns>
247: size_t _write_file_async(Concurrency::streams::details::_file_info_impl* fInfo,
248:                          Concurrency::streams::details::_filestream_callback* callback,
249:                          const void* ptr,
250:                          size_t count,
251:                          size_t position)
252: {
253:     ++fInfo->m_outstanding_writes;
254: 
255:     pplx::create_task([=]() -> void {
256:         off_t abs_position;
257:         bool must_restore_pos;
258:         off_t orig_pos;
259:         if (position == static_cast<size_t>(-1))
260:         {
261:             orig_pos = lseek(fInfo->m_handle, 0, SEEK_CUR);
262:             abs_position = lseek(fInfo->m_handle, 0, SEEK_END);
263:             must_restore_pos = true;
264:         }
265:         else
266:         {
267:             abs_position = position;
268:             orig_pos = 0;
269:             must_restore_pos = false;
270:         }
271: 
272:         auto bytes_written = pwrite(fInfo->m_handle, ptr, count, abs_position);
273:         if (bytes_written == -1)
274:         {
275:             callback->on_error(std::make_exception_ptr(utility::details::create_system_error(errno)));
276:         }
277: 
278:         if (must_restore_pos)
279:         {
280:             lseek(fInfo->m_handle, orig_pos, SEEK_SET);
281:         }
282: 
283:         callback->on_completed(bytes_written);
284: 
285:         {
286:             pplx::extensibility::scoped_recursive_lock_t lock(fInfo->m_lock);
287: 
288:             // Decrement the counter of outstanding write events.
289:             if (--fInfo->m_outstanding_writes == 0)
290:             {
291:                 // If this was the last one, signal all objects waiting for it to complete.
292: 
293:                 for (auto iter = fInfo->m_sync_waiters.begin(); iter != fInfo->m_sync_waiters.end(); iter++)
294:                 {
295:                     (*iter)->on_completed(0);
296:                 }
297:                 fInfo->m_sync_waiters.clear();
298:             }
299:         }
300:     });
301: 
302:     return 0;
303: }
