371: static const size_t PageSize = 512;
372: 
373: size_t _fill_buffer_fsb(_file_info_impl* fInfo, _filestream_callback* callback, size_t count, size_t charSize)
374: {
375:     size_t byteCount = count * charSize;
376:     if (fInfo->m_buffer == nullptr)
377:     {
378:         fInfo->m_bufsize = (std::max)(PageSize, byteCount);
379:         fInfo->m_buffer = new char[static_cast<size_t>(fInfo->m_bufsize)];
380:         fInfo->m_bufoff = fInfo->m_rdpos;
381: 
382:         auto cb = create_callback(fInfo, callback, [=](size_t result) {
383:             pplx::extensibility::scoped_recursive_lock_t lock(fInfo->m_lock);
384:             fInfo->m_buffill = result / charSize;
385:             callback->on_completed(result);
386:         });
387: 
388:         return _read_file_async(fInfo, cb, (uint8_t*)fInfo->m_buffer, fInfo->m_bufsize, fInfo->m_rdpos * charSize);
389:     }
390: 
391:     // First, we need to understand how far into the buffer we have already read
392:     // and how much remains.
393: 
394:     size_t bufpos = fInfo->m_rdpos - fInfo->m_bufoff;
395:     size_t bufrem = fInfo->m_buffill - bufpos;
396: 
397:     if (bufrem < count)
398:     {
399:         fInfo->m_bufsize = (std::max)(PageSize, byteCount);
400: 
401:         // Then, we allocate a new buffer.
402: 
403:         char* newbuf = new char[static_cast<size_t>(fInfo->m_bufsize)];
404: 
405:         // Then, we copy the unread part to the new buffer and delete the old buffer
406: 
407:         if (bufrem > 0) memcpy(newbuf, fInfo->m_buffer + bufpos * charSize, bufrem * charSize);
408: 
409:         delete[] fInfo->m_buffer;
410:         fInfo->m_buffer = newbuf;
411: 
412:         // Then, we read the remainder of the count into the new buffer
413:         fInfo->m_bufoff = fInfo->m_rdpos;
414: 
415:         auto cb = create_callback(fInfo, callback, [=](size_t result) {
416:             pplx::extensibility::scoped_recursive_lock_t lock(fInfo->m_lock);
417:             fInfo->m_buffill = result / charSize;
418:             callback->on_completed(result + bufrem * charSize);
419:         });
420: 
421:         return _read_file_async(fInfo,
422:                                 cb,
423:                                 (uint8_t*)fInfo->m_buffer + bufrem * charSize,
424:                                 fInfo->m_bufsize - bufrem * charSize,
425:                                 (fInfo->m_rdpos + bufrem) * charSize);
426:     }
427:     else
428:         return byteCount;
429: }
