431: /// <summary>
432: /// Read data from a file stream into a buffer
433: /// </summary>
434: /// <param name="info">The file info record of the file</param>
435: /// <param name="callback">A pointer to the callback interface to invoke when the write request is completed.</param>
436: /// <param name="ptr">A pointer to a buffer where the data should be placed</param>
437: /// <param name="count">The size (in bytes) of the buffer</param>
438: /// <returns>0 if the read request is still outstanding, -1 if the request failed, otherwise the size of the data read
439: /// into the buffer</returns>
440: size_t _getn_fsb(Concurrency::streams::details::_file_info* info,
441:                  Concurrency::streams::details::_filestream_callback* callback,
442:                  void* ptr,
443:                  size_t count,
444:                  size_t charSize)
445: {
446:     if (callback == nullptr || info == nullptr) return static_cast<size_t>(-1);
447: 
448:     _file_info_impl* fInfo = (_file_info_impl*)info;
449: 
450:     pplx::extensibility::scoped_recursive_lock_t lock(info->m_lock);
451: 
452:     if (fInfo->m_handle == -1) return static_cast<size_t>(-1);
453: 
454:     size_t byteCount = count * charSize;
455: 
456:     if (fInfo->m_buffer_reads)
457:     {
458:         auto cb = create_callback(fInfo, callback, [=](size_t read) {
459:             auto copy = (std::min)(read, byteCount);
460:             auto bufoff = fInfo->m_rdpos - fInfo->m_bufoff;
461:             memcpy(ptr, fInfo->m_buffer + bufoff * charSize, copy);
462:             fInfo->m_atend = copy < byteCount;
463:             callback->on_completed(copy);
464:         });
465: 
466:         size_t read = _fill_buffer_fsb(fInfo, cb, count, charSize);
467: 
468:         if (static_cast<int>(read) > 0)
469:         {
470:             auto copy = (std::min)(read, byteCount);
471:             auto bufoff = fInfo->m_rdpos - fInfo->m_bufoff;
472:             memcpy(ptr, fInfo->m_buffer + bufoff * charSize, copy);
473:             fInfo->m_atend = copy < byteCount;
474:             return copy;
475:         }
476: 
477:         return read;
478:     }
479:     else
480:     {
481:         return _read_file_async(fInfo, callback, ptr, count, fInfo->m_rdpos * charSize);
482:     }
483: }
