485: /// <summary>
486: /// Write data from a buffer into the file stream.
487: /// </summary>
488: /// <param name="info">The file info record of the file</param>
489: /// <param name="callback">A pointer to the callback interface to invoke when the write request is completed.</param>
490: /// <param name="ptr">A pointer to a buffer where the data should be placed</param>
491: /// <param name="count">The size (in bytes) of the buffer</param>
