38: struct threadpool_impl final : crossplat::threadpool
39: {
40:     threadpool_impl(size_t n) : crossplat::threadpool(n), m_work(m_service)
41:     {
42:         for (size_t i = 0; i < n; i++)
43:             add_thread();
44:     }
45: 
46:     threadpool_impl(const threadpool_impl&) = delete;
47:     threadpool_impl& operator=(const threadpool_impl&) = delete;
48: 
49:     ~threadpool_impl()
50:     {
51:         m_service.stop();
52:         for (auto iter = m_threads.begin(); iter != m_threads.end(); ++iter)
53:         {
54:             (*iter)->join();
55:         }
56:     }
57: 
58:     threadpool_impl& get_shared() { return *this; }
59: 
60: private:
61:     void add_thread()
62:     {
63:         m_threads.push_back(
64:             std::unique_ptr<boost::asio::detail::thread>(new boost::asio::detail::thread([&] { thread_start(this); })));
65:     }
66: 
67: #if defined(__ANDROID__)
68:     static void detach_from_java(void*) { crossplat::JVM.load()->DetachCurrentThread(); }
69: #endif // __ANDROID__
70: 
71:     static void* thread_start(void* arg) CPPREST_NOEXCEPT
72:     {
73: #if defined(__ANDROID__)
74:         // Calling get_jvm_env() here forces the thread to be attached.
75:         crossplat::get_jvm_env();
76:         pthread_cleanup_push(detach_from_java, nullptr);
77: #endif // __ANDROID__
78:         threadpool_impl* _this = reinterpret_cast<threadpool_impl*>(arg);
79:         _this->m_service.run();
80: #if defined(__ANDROID__)
81:         pthread_cleanup_pop(true);
82: #endif // __ANDROID__
83:         return arg;
84:     }
85: 
86:     std::vector<std::unique_ptr<boost::asio::detail::thread>> m_threads;
87:     boost::asio::io_service::work m_work;
88: };
