169: std::pair<bool, platform_shared_threadpool*> initialize_shared_threadpool(size_t num_threads)
170: {
171:     static uninitialized<platform_shared_threadpool> uninit_threadpool;
172:     bool initialized_this_time = false;
173:     static std::once_flag of;
